export type BusinessType = 'Food' | 'Fashion' | 'Trading' | 'Production' | 'Services';

export interface User {
  phoneNumber: string;
  name: string;
  hasCompletedOnboarding: boolean;
  isAdmin: boolean;
}

export interface Business {
  id: string; // Required for sync
  user_id?: string;
  name: string;
  type: BusinessType;
  location?: string;
  startDate: string;
  isActive: boolean;
  synced?: boolean;
}

export interface Transaction {
  id: string;
  userId: string;
  businessId: string;
  type: 'sale' | 'expense';
  amount: number;
  category: string;
  date: string;
  note?: string;
  synced?: boolean;
}

export interface Saving {
  id: string;
  businessId: string;
  amount: number;
  destination: 'Bank' | 'Mobile Money';
  date: string;
  synced?: boolean;
}

export interface AppState {
  user: User | null;
  business: Business | null;
  transactions: Transaction[];
  savings: Saving[];
  customCategories: string[];
  entryCount: number;
  showCategoryPrompt: boolean;
  isOnline: boolean;
  isSyncing: boolean;
}

import Dexie, { type Table } from 'dexie';
import { Transaction, Saving, Business } from '../types';

export class DigiSheDB extends Dexie {
  businesses!: Table<Business>;
  transactions!: Table<Transaction>;
  savings!: Table<Saving>;
  profiles!: Table<{ phone: string; name: string; has_completed_onboarding: boolean; is_admin: boolean }>;

  constructor() {
    super('DigiSheDB');
    this.version(1).stores({
      businesses: 'id, user_id, synced',
      transactions: 'id, businessId, type, synced',
      savings: 'id, businessId, synced',
      profiles: 'phone'
    });
  }
}

export const db = new DigiSheDB();

