        <div className="grid grid-cols-2 gap-4">
          <StatBox label="Sales" value={`$${stats.sales}`} color="bg-emerald-500" icon={<TrendingUp size={20}/>} />
          <StatBox label="Expenses" value={`$${stats.expenses}`} color="bg-rose-500" icon={<TrendingDown size={20}/>} />
