// --- Helper Functions ---
const formatDate = (date: Date) => date.toISOString().split('T')[0];

/**
 * Normalizes phone numbers specifically for Ghana (233).
 * Handles variations like 050..., 50..., 23350..., 233050..., etc.
 * Ensures that 0503088600 and 233503088600 are treated as the same identity.
 */
const normalizePhone = (phone: string): string => {
  let cleaned = phone.replace(/\D/g, '');

  // Remove 233 prefix if it exists to normalize the core number
  if (cleaned.startsWith('233')) {
    cleaned = cleaned.substring(3);
  }

  // Remove leading 0 if it exists
  if (cleaned.startsWith('0')) {
    cleaned = cleaned.substring(1);
  }

  // Return standard 233 prefixed number
  return '233' + cleaned;
};

const getWeeklyData = (transactions: Transaction[]) => {
  const last7Days = Array.from({ length: 7 }, (_, i) => {
    const d = new Date();
    d.setDate(d.getDate() - i);
    return formatDate(d);
  }).reverse();

  return last7Days.map(date => {
    const daily = transactions.filter(t => t.date === date);
    return {
      date: new Date(date).toLocaleDateString('en-US', { weekday: 'short' }),
      fullDate: date,
      sales: daily.filter(t => t.type === 'sale').reduce((acc, t) => acc + t.amount, 0),
      expenses: daily.filter(t => t.type === 'expense').reduce((acc, t) => acc + t.amount, 0)
    };
  });
};

