// --- Main App ---
export default function App() {
  const [state, setState] = useState<AppState>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      return saved ? { ...JSON.parse(saved), isOnline: navigator.onLine, isSyncing: false } : initialState;
    } catch (e) { return initialState; }
  });
  const [insight, setInsight] = useState("Record-keeping is the first step to success!");
  const [isInitializing, setIsInitializing] = useState(true);
  const [isSyncingAfterLogin, setIsSyncingAfterLogin] = useState(false);
  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'success'>('idle');

  // Handle Online/Offline Status
  useEffect(() => {
    const handleOnline = () => setState(prev => ({ ...prev, isOnline: true }));
    const handleOffline = () => setState(prev => ({ ...prev, isOnline: false }));
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Sync state to local storage for quick access
  useEffect(() => {
    if (state.user) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    }
  }, [state]);

  // Initialize Data from Local DB then try Remote if Online
  useEffect(() => {
    const initialize = async () => {
      const profile = await db.profiles.toCollection().first();
      const business = await db.businesses.toCollection().first();
      const transactions = await db.transactions.toArray();
      const savings = await db.savings.toArray();

      if (profile) {
        setState(prev => ({
          ...prev,
          user: { phoneNumber: profile.phone, name: profile.name, isAdmin: profile.is_admin, hasCompletedOnboarding: profile.has_completed_onboarding },
          business: business || null,
          transactions,
          savings,
          entryCount: transactions.length
        }));
      }

      // If online, try to pull latest from Supabase
      if (navigator.onLine && profile) {
        await hydrateFromRemote(profile.phone);
      }

      setTimeout(() => setIsInitializing(false), 1000);
    };
    initialize();
  }, []);

  // Sync effect to update insights using Gemini
  useEffect(() => {
    const fetchInsight = async () => {
      if (state.business && state.transactions.length > 0) {
        const text = await getBusinessInsight(state.business, state.transactions);
        setInsight(text);
      }
    };
    fetchInsight();
  }, [state.business, state.transactions.length]);

  // Hydrate local DB from Supabase
  const hydrateFromRemote = async (phone: string) => {
    try {
      const normalized = normalizePhone(phone);
      const { data: profile } = await supabase.from('profiles').select('*').eq('phone', normalized).maybeSingle();
      if (!profile) return;

      const { data: business } = await supabase.from('businesses').select('*').eq('user_id', profile.id).maybeSingle();

      let onboardingStatus = profile.has_completed_onboarding;
      let bizData: Business | null = null;
      let txData: Transaction[] = [];
      let svData: Saving[] = [];

      if (business) {
        onboardingStatus = true; // Business exists, definitely onboarded
        const { data: txs } = await supabase.from('transactions').select('*').eq('business_id', business.id);
        const { data: svs } = await supabase.from('savings').select('*').eq('business_id', business.id);

        bizData = { id: business.id, name: business.name, type: business.type as BusinessType, location: business.location, isActive: business.is_active, startDate: business.start_date, synced: true };
        txData = (txs || []).map(t => ({ id: t.id, userId: normalized, businessId: business.id, type: t.type, amount: parseFloat(t.amount), category: t.category, date: t.date, synced: true }));
        svData = (svs || []).map(s => ({ id: s.id, businessId: business.id, amount: parseFloat(s.amount), destination: s.destination, date: s.date, synced: true }));

        // Update Local DB
        await db.businesses.put(bizData);
        await db.transactions.bulkPut(txData);
        await db.savings.bulkPut(svData);
      }

      // Reconciliation: If business found but onboarding was false, update it.
      if (onboardingStatus !== profile.has_completed_onboarding) {
        await db.profiles.update(normalized, { has_completed_onboarding: onboardingStatus });
        if (navigator.onLine) {
            await supabase.from('profiles').update({ has_completed_onboarding: onboardingStatus }).eq('phone', normalized);
        }
      }

      // Update Local Profile Status
      await db.profiles.put({ phone: profile.phone, name: profile.name, is_admin: profile.is_admin, has_completed_onboarding: onboardingStatus });

      // Update State
      setState(prev => ({
        ...prev,
        user: { phoneNumber: profile.phone, name: profile.name, isAdmin: profile.is_admin, hasCompletedOnboarding: onboardingStatus },
        business: bizData,
        transactions: txData,
        savings: svData,
        entryCount: txData.length
      }));

    } catch (e) {
      console.error("Hydration failed (might be offline/slow):", e);
    }
  };

  // MANUAL SYNC HANDLER
  const handleManualSync = async () => {
    if (!state.user || !state.business || !state.isOnline) return;

    setSyncStatus('syncing');
    try {
      const toSyncTxs = state.transactions.filter(t => !t.synced);
      const toSyncSvs = state.savings.filter(s => !s.synced);
      const toSyncBiz = !state.business.synced ? state.business : null;

      // 1. Sync Business if needed
      if (toSyncBiz) {
        await supabase.from('businesses').upsert({
          id: toSyncBiz.id,
          name: toSyncBiz.name,
          type: toSyncBiz.type,
          location: toSyncBiz.location,
          is_active: toSyncBiz.isActive,
          start_date: toSyncBiz.startDate
        });
        await db.businesses.update(toSyncBiz.id, { synced: true });
      }

      // 2. Sync Transactions
      if (toSyncTxs.length > 0) {
        const payload = toSyncTxs.map(t => ({
          id: t.id,
          business_id: t.businessId,
          type: t.type,
          amount: t.amount,
          category: t.category,
          date: t.date
        }));
        await supabase.from('transactions').upsert(payload);
        for (const t of toSyncTxs) await db.transactions.update(t.id, { synced: true });
      }

      // 3. Sync Savings
      if (toSyncSvs.length > 0) {
        const payload = toSyncSvs.map(s => ({
          id: s.id,
          business_id: s.businessId,
          amount: s.amount,
          destination: s.destination,
          date: s.date
        }));
        await supabase.from('savings').upsert(payload);
        for (const s of toSyncSvs) await db.savings.update(s.id, { synced: true });
      }

      // 4. Update UI State
      const updatedTxs = state.transactions.map(t => ({ ...t, synced: true }));
      const updatedSvs = state.savings.map(s => ({ ...s, synced: true }));
      setState(prev => ({ 
        ...prev, 
        transactions: updatedTxs, 
        savings: updatedSvs, 
        business: prev.business ? { ...prev.business, synced: true } : null 
      }));

      setSyncStatus('success');
      setTimeout(() => setSyncStatus('idle'), 3000);
    } catch (error) {
      console.error("Sync failed:", error);
      alert("Sync failed. Please check your connection.");
      setSyncStatus('idle');
    }
  };

  const addTransaction = async (type: 'sale' | 'expense', amount: number, category: string) => {
    if (!state.business) return;
    const dateStr = formatDate(new Date());
    const newTx: Transaction = { 
      id: crypto.randomUUID(), 
      userId: state.user?.phoneNumber || 'unknown', 
      businessId: state.business.id,
      type, 
      amount, 
      category, 
      date: dateStr, 
      synced: false 
    };

    // Write Local
    await db.transactions.add(newTx);
    setState(prev => ({ 
      ...prev, 
      transactions: [...prev.transactions, newTx], 
      entryCount: prev.entryCount + 1,
      showCategoryPrompt: (prev.entryCount + 1) === 3
    }));
  };

  const addSaving = async (amount: number, destination: 'Bank' | 'Mobile Money') => {
    if (!state.business) return;
    const dateStr = formatDate(new Date());
    const newS: Saving = { 
      id: crypto.randomUUID(), 
      businessId: state.business.id, 
      amount, 
      destination, 
      date: dateStr, 
      synced: false 
    };

    // Write Local
    await db.savings.add(newS);
    setState(prev => ({ ...prev, savings: [...prev.savings, newS] }));
  };

  const performLogout = async () => { 
    localStorage.removeItem(STORAGE_KEY); 
    await db.delete();
    window.location.reload();
  };

  if (isInitializing) return <SplashScreen />;

  const unsyncedCount = state.transactions.filter(t => !t.synced).length + state.savings.filter(s => !s.synced).length;

  return (
    <HashRouter>
      <div className="min-h-screen bg-slate-50">
        <Routes>
          <Route path="/" element={<LandingPage user={state.user} />} />
          <Route path="/login" element={
            isSyncingAfterLogin ? <SplashScreen /> : (
              !state.user ? (
                <AuthPage 
                  onAuthComplete={async (p) => {
                    setIsSyncingAfterLogin(true);
                    const normalized = normalizePhone(p.phone);
                    const u = { 
                      phoneNumber: normalized, 
                      name: p.name, 
                      isAdmin: p.is_admin, 
                      hasCompletedOnboarding: p.has_completed_onboarding 
                    };

                    // Pre-emptively store in local DB
                    await db.profiles.put(p);

                    // Set current state (so we can start navigation)
                    setState(prev => ({...prev, user: u }));

                    // Immediately trigger full hydration to fetch existing business
                    if (navigator.onLine) {
                      await hydrateFromRemote(normalized);
                    }

                    setIsSyncingAfterLogin(false);
                  }} 
                  onMissingTables={() => {}} 
                />
              ) : (
                state.user.hasCompletedOnboarding ? (
                  state.business?.isActive ? <Navigate to="/dashboard" replace /> : <Navigate to="/pending" replace />
                ) : <Navigate to="/onboarding" replace />
              )
            )
          } />

          <Route path="/onboarding" element={state.user ? <OnboardingPage onComplete={async (biz) => {
            const id = crypto.randomUUID();
            const fullBiz: Business = { 
              id, 
              name: biz.name || 'My Business', 
              type: biz.type || 'Food', 
              location: biz.location, 
              isActive: true, 
              startDate: biz.startDate || formatDate(new Date()), 
              synced: false 
            };

            // Persist onboarding status to Supabase and Local DB
            if (state.user?.phoneNumber) {
              const normalized = normalizePhone(state.user.phoneNumber);

              // Local update
              await db.profiles.update(normalized, { has_completed_onboarding: true });

              // Remote update if online
              if (navigator.onLine) {
                try {
                  await supabase.from('profiles').update({ has_completed_onboarding: true }).eq('phone', normalized);
                } catch (e) {
                  console.warn("Failed to update onboarding status on remote server", e);
                }
              }
            }

            await db.businesses.add(fullBiz);
            setState(prev => ({ ...prev, business: fullBiz, user: prev.user ? { ...prev.user, hasCompletedOnboarding: true } : null }));
          }} /> : <Navigate to="/login" replace />} />

          <Route 
            path="/dashboard" 
            element={state.business?.isActive ? 
              <Dashboard 
                state={state} 
                onLogout={() => setShowLogoutConfirm(true)} 
                insight={insight} 
                syncStatus={syncStatus}
                unsyncedCount={unsyncedCount}
                handleManualSync={handleManualSync}
              /> : <Navigate to="/pending" replace />} 
          />
          <Route path="/savings" element={<SavingsHub state={state} />} />
          <Route path="/record-saving" element={<RecordSavingPage onSave={addSaving} />} />
          <Route path="/record/:type" element={<RecordRouteHandler user={state.user} business={state.business} customCategories={state.customCategories} transactions={state.transactions} onSave={addTransaction} />} />
          <Route path="/pending" element={<PendingActivationPage onLogout={() => setShowLogoutConfirm(true)} />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </div>
      {showLogoutConfirm && <LogoutConfirmModal onConfirm={performLogout} onCancel={() => setShowLogoutConfirm(false)} />}
    </HashRouter>
  );
}

