const AuthPage: React.FC<{ onAuthComplete: (profile: any) => void; onMissingTables: () => void }> = ({ onAuthComplete, onMissingTables }) => {
  const [phone, setPhone] = useState('');
  const [name, setName] = useState('');
  const [code, setCode] = useState('');
  const [step, setStep] = useState<'phone' | 'otp'>('phone');
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSendOTP = async () => {
    if (!phone) return setError('Enter phone number');
    setIsLoading(true);
    setError('');
    try {
      const { data, error: err } = await supabase.functions.invoke('otp-handler', {
        body: { action: 'send', phone, name, mode }
      });
      if (err || data.error) throw new Error(err?.message || data.error);
      if (data.success === false) throw new Error(data.error);
      setStep('otp');
    } catch (e: any) {
      setError(e.message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleVerifyOTP = async () => {
    if (!code) return setError('Enter code');
    setIsLoading(true);
    setError('');
    try {
      const { data, error: err } = await supabase.functions.invoke('otp-handler', {
        body: { action: 'verify', phone, code, name }
      });
      if (err || data.error) throw new Error(err?.message || data.error);
      if (data.success && data.profile) {
        onAuthComplete(data.profile);
      } else {
        throw new Error(data.error || 'Invalid code');
      }
    } catch (e: any) {
      setError(e.message);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-white p-6 flex flex-col items-center justify-center space-y-8">
      <div className="text-center space-y-2">
        <h2 className="text-4xl font-black text-slate-900 tracking-tight">{mode === 'login' ? 'Welcome Back' : 'Join DigiShe'}</h2>
        <p className="text-slate-500 font-medium">Verify your phone to start recording.</p>
      </div>

      <Card className="w-full max-w-md space-y-6 shadow-xl border-slate-100">
        {step === 'phone' ? (
          <>
            <div className="flex gap-2 p-1.5 bg-slate-100 rounded-2xl mb-4">
              <button onClick={() => setMode('login')} className={`flex-1 py-2.5 rounded-xl text-sm font-black uppercase tracking-wider transition-all ${mode === 'login' ? 'bg-white shadow-md text-purple-600' : 'text-slate-400'}`}>Login</button>
              <button onClick={() => setMode('register')} className={`flex-1 py-2.5 rounded-xl text-sm font-black uppercase tracking-wider transition-all ${mode === 'register' ? 'bg-white shadow-md text-purple-600' : 'text-slate-400'}`}>Register</button>
            </div>
            {mode === 'register' && <Input label="Full Name" placeholder="e.g. Abena Serwaa" value={name} onChange={e => setName(e.target.value)} />}
            <Input label="Phone Number" placeholder="e.g. 0503088600" value={phone} onChange={e => setPhone(e.target.value)} type="tel" />
            {error && <div className="p-3 bg-rose-50 text-rose-500 text-sm font-bold rounded-xl flex items-center gap-2 animate-in fade-in"><AlertCircle size={16}/> {error}</div>}
            <Button className="w-full" size="xl" onClick={handleSendOTP} disabled={isLoading}>
              {isLoading ? <Loader2 className="animate-spin" /> : 'Continue'}
            </Button>
          </>
        ) : (
          <>
            <div className="space-y-2 text-center">
              <p className="text-sm font-bold text-slate-400 uppercase tracking-widest">Verify Code</p>
              <p className="text-slate-600">Sent to <b>{phone}</b></p>
            </div>
            <Input placeholder="123456" className="text-center text-2xl tracking-[0.5em] font-black" value={code} onChange={e => setCode(e.target.value)} maxLength={6} />
            {error && <div className="p-3 bg-rose-50 text-rose-500 text-sm font-bold rounded-xl flex items-center gap-2"><AlertCircle size={16}/> {error}</div>}
            <Button className="w-full" size="xl" onClick={handleVerifyOTP} disabled={isLoading}>
              {isLoading ? <Loader2 className="animate-spin" /> : 'Enter Ledger'}
            </Button>
            <button onClick={() => setStep('phone')} className="w-full text-slate-400 text-xs font-black uppercase tracking-widest py-2 hover:text-purple-600 transition-colors">Change number</button>
          </>
        )}
      </Card>

      <p className="text-slate-400 text-xs font-medium max-w-xs text-center">By continuing, you agree to our terms of service and privacy policy.</p>
    </div>
  );
};

