import { Button, Card, Input, StatBox } from './components/UI';
import { supabase } from './services/supabase';
import { db } from './services/db';
import { 
  PlusCircle, 
  MinusCircle, 
  TrendingUp, 
  TrendingDown, 
  Store, 
  ArrowRight,
  Sparkles,
  LogOut,
  ChevronLeft,
  Loader2,
  AlertCircle,
  WifiOff,
  CloudUpload,
  CloudCheck,
  RefreshCw,
  Timer,
