                      <div className="flex items-center gap-2 mt-0.5">
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-wider">{new Date(t.date).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}</p>
                        {!t.synced && <span className="flex items-center gap-1 text-[9px] font-black text-purple-400 uppercase tracking-tighter"><CloudUpload size={10} /> Local</span>}
                      </div>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className={`font-black text-xl tracking-tighter ${t.type === 'sale' ? 'text-emerald-600' : 'text-rose-600'}`}>
                      {t.type === 'sale' ? '+' : '-'}${t.amount.toFixed(2)}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </main>

      <div className="fixed bottom-0 left-0 right-0 bg-white/80 backdrop-blur-xl border-t p-5 pb-9 max-w-4xl mx-auto grid grid-cols-2 gap-4 z-50">
        <Button variant="sale" size="lg" className="shadow-xl shadow-emerald-500/20 py-4 rounded-2xl" onClick={() => navigate('/record/sale')}>
          <PlusCircle size={22} /> Add Sale
        </Button>
        <Button variant="expense" size="lg" className="shadow-xl shadow-rose-500/20 py-4 rounded-2xl" onClick={() => navigate('/record/expense')}>
          <MinusCircle size={22} /> Add Expense
        </Button>
      </div>
    </div>
  );
};

