const Dashboard: React.FC<{ 
  state: AppState; 
  onLogout: () => void; 
  insight: string;
  syncStatus: 'idle' | 'syncing' | 'success';
  unsyncedCount: number;
  handleManualSync: () => void;
}> = ({ state, onLogout, insight, syncStatus, unsyncedCount, handleManualSync }) => {
  const navigate = useNavigate();
  const stats = useMemo(() => {
    const sales = state.transactions.filter(t => t.type === 'sale').reduce((acc, t) => acc + t.amount, 0);
    const expenses = state.transactions.filter(t => t.type === 'expense').reduce((acc, t) => acc + t.amount, 0);
    return { sales, expenses, balance: sales - expenses };
  }, [state.transactions]);

  return (
    <div className="pb-24">
      <header className="bg-white px-6 py-4 border-b flex flex-col gap-4 sticky top-0 z-[150] shadow-sm">
        <div className="flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="bg-purple-600 p-2.5 rounded-2xl text-white shadow-lg shadow-purple-500/20">
              <Store size={22} />
            </div>
            <div>
              <h1 className="text-xl font-black text-slate-800 tracking-tight leading-none mb-1">{state.business?.name}</h1>
              <div className="flex items-center gap-2">
                <span className="text-[10px] font-black text-purple-600 uppercase tracking-widest">{state.business?.type}</span>
                <span className={`flex items-center gap-1 px-1.5 py-0.5 rounded-full text-[9px] font-black uppercase tracking-tight ${state.isOnline ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                  {state.isOnline ? <Globe size={10} /> : <WifiOff size={10} />}
                  {state.isOnline ? 'Online' : 'Offline'}
                </span>
              </div>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button 
              onClick={handleManualSync}
              disabled={syncStatus === 'syncing' || !state.isOnline}
              className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all active:scale-95 shadow-sm border ${
                syncStatus === 'success' ? 'bg-emerald-500 border-emerald-500 text-white' : 
                syncStatus === 'syncing' ? 'bg-purple-50 border-purple-100 text-purple-600 animate-pulse' : 
                (unsyncedCount > 0 && state.isOnline) ? 'bg-purple-600 border-purple-600 text-white shadow-md' : 'bg-slate-50 border-slate-100 text-slate-400'
              }`}
            >
              {syncStatus === 'success' ? <CloudCheck size={16} /> : 
               syncStatus === 'syncing' ? <Loader2 size={16} className="animate-spin" /> : 
               <CloudUpload size={16} />}
              <span className="hidden sm:inline">
                {syncStatus === 'success' ? 'Synced!' : syncStatus === 'syncing' ? 'Syncing...' : `Sync Now ${unsyncedCount > 0 ? `(${unsyncedCount})` : ''}`}
              </span>
            </button>
            <button onClick={onLogout} className="p-3 rounded-xl bg-slate-50 text-slate-400 hover:bg-rose-50 hover:text-rose-500 transition-all border border-slate-100">
              <LogOut size={22} />
            </button>
          </div>
        </div>
      </header>

      <main className="p-6 max-w-4xl mx-auto space-y-6">
        <Card className="bg-gradient-to-br from-purple-600 to-indigo-700 text-white border-none shadow-xl relative overflow-hidden">
          <div className="absolute top-0 right-0 p-8 opacity-10 pointer-events-none"><Sparkles size={120} /></div>
          <div className="flex items-start gap-3 relative z-10">
            <div className="p-2 bg-white/20 rounded-xl backdrop-blur-sm"><Sparkles className="text-white" size={20} /></div>
            <div>
              <p className="text-xs font-black opacity-70 uppercase tracking-[0.2em] mb-1">Business Insight</p>
              <p className="text-lg font-medium italic leading-snug">"{insight}"</p>
            </div>
          </div>
        </Card>

        <div className="grid grid-cols-2 gap-4">
          <StatBox label="Sales" value={`$${stats.sales.toFixed(2)}`} color="bg-emerald-500" icon={<TrendingUp size={20}/>} />
          <StatBox label="Expenses" value={`$${stats.expenses.toFixed(2)}`} color="bg-rose-500" icon={<TrendingDown size={20}/>} />
        </div>

        <div className="space-y-4 pt-4">
          <div className="flex justify-between items-center">
            <h3 className="font-black text-slate-800 uppercase tracking-widest text-xs">Recent Activity</h3>
          </div>
          {state.transactions.length === 0 ? (
            <div className="text-center py-16 space-y-4 bg-white rounded-3xl border-2 border-dashed border-slate-100">
              <p className="text-slate-400 font-bold">No records yet. Start by adding a sale!</p>
            </div>
          ) : (
            <div className="space-y-3">
              {state.transactions.slice().reverse().slice(0, 10).map(t => (
                <div key={t.id} className="bg-white p-4 rounded-2xl border border-slate-100 flex justify-between items-center shadow-sm">
                  <div className="flex items-center gap-4">
                    <div className={`p-3 rounded-xl ${t.type === 'sale' ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                      {t.type === 'sale' ? <PlusCircle size={22} /> : <MinusCircle size={22} />}
                    </div>
                    <div>
                      <p className="font-black text-slate-800 leading-tight">{t.category}</p>
                      <p className="text-[10px] text-slate-400 font-black uppercase tracking-wider">{new Date(t.date).toLocaleDateString()}</p>
                    </div>
                  </div>
                  <p className={`font-black text-xl tracking-tighter ${t.type === 'sale' ? 'text-emerald-600' : 'text-rose-600'}`}>
                    {t.type === 'sale' ? '+' : '-'}${t.amount.toFixed(2)}
                  </p>
                </div>
              ))}
            </div>
          )}
        </div>
      </main>

      <div className="fixed bottom-0 left-0 right-0 bg-white/80 backdrop-blur-xl border-t p-5 pb-9 max-w-4xl mx-auto grid grid-cols-2 gap-4 z-50">
        <Button variant="sale" size="lg" onClick={() => navigate('/record/sale')}>
