const AuthPage: React.FC<{ onAuthComplete: (profile: any) => void; onMissingTables: () => void }> = ({ onAuthComplete }) => {
  const navigate = useNavigate();
  const [phone, setPhone] = useState('');
  const [name, setName] = useState('');
  const [code, setCode] = useState('');
  const [step, setStep] = useState<'phone' | 'otp'>('phone');
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSendOTP = async () => {
    if (!phone) return setError('Enter phone number');
    setIsLoading(true);
    setError('');

    try {
      const normalized = normalizePhone(phone);

      // Step 1: Explicitly check for user existence before attempting to send OTP
      const { data: profile, error: profileErr } = await supabase
        .from('profiles')
        .select('phone')
        .eq('phone', normalized)
        .maybeSingle();

      if (profileErr) {
        console.warn("User existence check failed locally, falling back to edge function", profileErr);
      }

      // Step 2: Stop and alert if the number is already registered during signup
      if (mode === 'register' && profile) {
        setError('This number is already registered. Please login instead.');
        setIsLoading(false);
        setMode('login'); // Switch to login mode for convenience
        return;
      }

      // Step 3: Stop and alert if the account is not found during login
      if (mode === 'login' && !profile && !profileErr) {
        setError('Account not found. Please register first.');
        setIsLoading(false);
        setMode('register'); // Switch to register mode for convenience
        return;
      }

      // Step 4: Proceed to invoke the OTP handler edge function
      const { data, error: err } = await supabase.functions.invoke('otp-handler', { 
        body: { action: 'send', phone: normalized, name, mode } 
      });

      if (err) throw new Error(err.message);
      if (data && data.error) throw new Error(data.error);

      setStep('otp');
    } catch (e: any) {
      console.error("Auth Exception:", e);
      setError(e.message || 'There was an unexpected error. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleVerifyOTP = async () => {
    if (!code) return setError('Enter code');
    setIsLoading(true);
    setError('');
    try {
      const normalized = normalizePhone(phone);
      const { data, error: err } = await supabase.functions.invoke('otp-handler', { 
        body: { action: 'verify', phone: normalized, code, name } 
      });
      if (err) throw new Error(err.message);
      if (data && data.error) throw new Error(data.error);
      if (data.success && data.profile) onAuthComplete(data.profile);
      else throw new Error(data.error || 'Invalid code');
    } catch (e: any) {
      setError(e.message);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-purple-600 flex flex-col items-center justify-center p-6 relative overflow-hidden">
      <div className="absolute -top-24 -left-24 w-96 h-96 bg-white/5 rounded-full blur-3xl"></div>
      <div className="absolute -bottom-24 -right-24 w-96 h-96 bg-purple-400/10 rounded-full blur-3xl"></div>

      <button 
        onClick={() => navigate('/')}
        className="absolute top-8 left-8 flex items-center gap-2 bg-white/10 text-white px-5 py-2.5 rounded-2xl text-sm font-bold backdrop-blur-md border border-white/10"
      >
        <Home size={18} />
        Back to Home
      </button>

      <div className="text-center space-y-4 mb-10 relative z-10">
        <div className="bg-white p-4 rounded-3xl inline-block shadow-2xl shadow-purple-900/20">
          <Store className="text-purple-600 w-12 h-12" fill="currentColor" fillOpacity={0.1} />
        </div>
        <div className="space-y-1">
          <h1 className="text-4xl font-black text-white tracking-tighter">DigiShe</h1>
          <p className="text-purple-100/80 font-medium text-lg">Digital bookkeeping for women entrepreneurs</p>
        </div>
      </div>

      <Card className="w-full max-w-md p-8 md:p-12 rounded-[2.5rem] shadow-2xl border-none relative z-10 space-y-10">
        {step === 'phone' ? (
          <>
            <div className="space-y-2">
              <h2 className="text-3xl font-black text-slate-900 tracking-tight">
                {mode === 'login' ? 'Welcome Back' : 'Create Account'}
              </h2>
            </div>

            <div className="space-y-6">
              {mode === 'register' && (
                <Input label="Full Name" placeholder="e.g. Abena Serwaa" value={name} onChange={e => setName(e.target.value)} />
              )}
              <Input label="Phone Number" placeholder="e.g. 0503088600" value={phone} onChange={e => setPhone(e.target.value)} type="tel" />

              {error && (
                <div className="p-4 bg-rose-50 text-rose-600 text-sm font-bold rounded-2xl flex items-center gap-3 border border-rose-100 animate-in shake duration-300">
                  <AlertCircle size={20} className="shrink-0" />
                  {error}
                </div>
              )}

              <Button className="w-full py-5 text-lg shadow-xl shadow-purple-500/20 rounded-2xl" size="xl" onClick={handleSendOTP} disabled={isLoading}>
                {isLoading ? <Loader2 className="animate-spin" /> : <span className="flex items-center gap-2">Continue <ArrowRight size={22} /></span>}
              </Button>
            </div>

            <div className="text-center pt-2">
              <button onClick={() => { setMode(mode === 'login' ? 'register' : 'login'); setError(''); }} className="text-purple-600 font-bold hover:underline">
                {mode === 'login' ? "Don't have an account? Register" : "Already have an account? Login"}
              </button>
            </div>
          </>
        ) : (
          <>
            <div className="space-y-2 text-center">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em]">Verify Code</p>
              <p className="text-slate-600 font-medium text-lg">Sent to <span className="font-black text-slate-900">{phone}</span></p>
            </div>
            <div className="space-y-8">
              <Input placeholder="000000" className="text-center text-4xl tracking-[0.5em] font-black h-20 border-2" value={code} onChange={e => setCode(e.target.value)} maxLength={6} autoFocus />
              {error && (
                <div className="p-4 bg-rose-50 text-rose-600 text-sm font-bold rounded-2xl flex items-center gap-3 border border-rose-100">
                  <AlertCircle size={20} className="shrink-0" />
                  {error}
                </div>
              )}
              <Button className="w-full py-5 text-lg shadow-xl shadow-purple-500/20 rounded-2xl" size="xl" onClick={handleVerifyOTP} disabled={isLoading}>
                {isLoading ? <Loader2 className="animate-spin" /> : 'Enter Ledger'}
              </Button>
              <button onClick={() => { setStep('phone'); setError(''); setCode(''); }} className="w-full text-slate-400 text-xs font-black uppercase tracking-widest py-2 hover:text-purple-600 transition-colors">Change number</button>
            </div>
          </>
        )}
      </Card>
    </div>
  );
};

