// --- Constants ---
const STORAGE_KEY = 'digishe_app_data_v4';
const SALES_CATEGORIES = ['Product sold', 'Service rendered', 'Other sales'];
const EXPENSE_CATEGORIES = ['Materials', 'Transport', 'Rent', 'Light Bill', 'Water Bill', 'Food', 'Other expenses'];
const SAVINGS_DESTINATIONS = ['Bank', 'Mobile Money', 'Other'];

const initialState: AppState = {
  user: null,
  business: null,
  transactions: [],
  savings: [],
  customCategories: [],
  entryCount: 0,
  showCategoryPrompt: false,
  isOnline: navigator.onLine,
  isSyncing: false
};

// --- Helper Functions ---
const formatDate = (date: Date) => date.toISOString().split('T')[0];

const normalizePhone = (phone: string): string => {
  let cleaned = phone.replace(/\D/g, '');
  if (cleaned.startsWith('233')) cleaned = cleaned.substring(3);
  if (cleaned.startsWith('0')) cleaned = cleaned.substring(1);
  return '233' + cleaned;
};

// --- Dashboard Components ---

const PerformanceChart: React.FC<{ transactions: Transaction[] }> = ({ transactions }) => {
  const data = useMemo(() => {
    const result = [];
    const now = new Date();

    // Calculate data for the last 7 days ending today
    for (let i = 6; i >= 0; i--) {
      const d = new Date(now);
      d.setDate(now.getDate() - i);
      const dateStr = formatDate(d);
      const dayName = d.toLocaleDateString('en-US', { weekday: 'short' });

      const daySales = transactions
        .filter(t => t.type === 'sale' && t.date === dateStr)
        .reduce((sum, t) => sum + t.amount, 0);

      const dayExpenses = transactions
        .filter(t => t.type === 'expense' && t.date === dateStr)
        .reduce((sum, t) => sum + t.amount, 0);

      result.push({ 
        name: dayName, 
        sales: parseFloat(daySales.toFixed(2)), 
        expenses: parseFloat(dayExpenses.toFixed(2)) 
      });
    }
    return result;
  }, [transactions]);

  return (
    <div className="h-[250px] w-full mt-4">
      <ResponsiveContainer width="100%" height="100%">
        <BarChart data={data} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
          <XAxis 
            dataKey="name" 
            axisLine={false} 
            tickLine={false} 
            tick={{ fontSize: 10, fill: '#94a3b8', fontWeight: 500 }}
            dy={10}
          />
          <YAxis hide />
          <Tooltip 
            cursor={{ fill: '#f8fafc' }}
            contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
          />
          <Legend 
            verticalAlign="top" 
            align="right" 
            height={36} 
            iconType="circle" 
            formatter={(value) => <span className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1">{value}</span>}
          />
          {/* Swapped order to match mockup: Expenses then Sales */}
          <Bar dataKey="expenses" fill="#f43f5e" radius={[4, 4, 0, 0]} name="Expenses" barSize={20} />
          <Bar dataKey="sales" fill="#10b981" radius={[4, 4, 0, 0]} name="Sales" barSize={20} />
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
};

