const PerformanceChart: React.FC<{ transactions: Transaction[] }> = ({ transactions }) => {
  const data = useMemo(() => {
    const result = [];
    const now = new Date();

    // Generate data for the last 7 days ending today (inclusive)
    for (let i = 6; i >= 0; i--) {
      const d = new Date(now);
      d.setDate(now.getDate() - i);
      const dateStr = formatDate(d);
      const dayName = d.toLocaleDateString('en-US', { weekday: 'short' });

      const daySales = transactions
        .filter(t => t.type === 'sale' && t.date === dateStr)
        .reduce((sum, t) => sum + t.amount, 0);

      const dayExpenses = transactions
        .filter(t => t.type === 'expense' && t.date === dateStr)
        .reduce((sum, t) => sum + t.amount, 0);

      result.push({ 
        name: dayName, 
        sales: parseFloat(daySales.toFixed(2)), 
        expenses: parseFloat(dayExpenses.toFixed(2)) 
      });
    }
    return result;
  }, [transactions]);

  return (
    <div className="h-[280px] w-full mt-4">
      <ResponsiveContainer width="100%" height="100%">
        <BarChart data={data} margin={{ top: 5, right: 10, left: -20, bottom: 0 }}>
          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
          <XAxis 
            dataKey="name" 
            axisLine={false} 
            tickLine={false} 
            tick={{ fontSize: 11, fill: '#94a3b8', fontWeight: 600 }}
            dy={10}
          />
          <YAxis 
            hide 
            domain={[0, (dataMax: number) => Math.max(10, dataMax * 1.1)]}
          />
          <Tooltip 
            cursor={{ fill: '#f8fafc', radius: 4 }}
            contentStyle={{ 
              borderRadius: '16px', 
              border: 'none', 
              boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1)',
              padding: '12px'
            }}
            itemStyle={{ fontSize: '12px', fontWeight: 'bold', padding: '2px 0' }}
          />
          <Legend 
            verticalAlign="top" 
            align="right" 
            height={40} 
            iconType="circle" 
            iconSize={8}
            formatter={(value) => <span className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 ml-1">{value}</span>}
          />
          <Bar 
            dataKey="expenses" 
            fill="#f43f5e" 
            radius={[6, 6, 0, 0]} 
            name="Expenses" 
            barSize={18} 
            animationDuration={1500}
            animationBegin={200}
          />
          <Bar 
            dataKey="sales" 
            fill="#10b981" 
            radius={[6, 6, 0, 0]} 
            name="Sales" 
            barSize={18} 
            animationDuration={1500}
            animationBegin={0}
          />
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
};

