          <Bar 
            dataKey="sales" 
            fill="#10b981" 
            radius={[6, 6, 0, 0]} 
            name="Sales" 
            barSize={18} 
            animationDuration={1500}
            animationBegin={0}
          />
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
};

