        <button onClick={() => navigate('/dashboard')} className="p-2.5 bg-slate-50 rounded-xl text-slate-400 border border-slate-100 hover:bg-slate-100 transition-colors">
          <ChevronLeft size={22}/>
        </button>
        <h1 className="text-lg font-black text-slate-900 tracking-tight capitalize leading-none">Record {type}</h1>
      </header>

      <main className="p-4 max-w-4xl mx-auto space-y-8 mt-4">
        <Card className="p-8 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-8 bg-white">
          <div className="space-y-2">
            <label className="text-sm font-black text-slate-700 ml-1">Category</label>
